function toTraditional(value) {
  if (typeof value !== "string") return value;
  let output = value;
  traditionalPhrases.forEach((replacement, phrase) => { output = output.split(phrase).join(replacement); });
  output = Array.from(output, (character) => traditionalCharacters[character] || character).join("");
  traditionalPostPhrases.forEach((replacement, phrase) => { output = output.split(phrase).join(replacement); });
  return output;
}
