const heroCriticalReady = (() => {
  if (!heroPriorityImage) return Promise.resolve();
  const imageReady = new Promise((resolve) => {
    const finish = () => {
      if (typeof heroPriorityImage.decode === "function") heroPriorityImage.decode().catch(() => undefined).finally(resolve);
      else resolve();
    };
    if (heroPriorityImage.complete) finish();
    else {
      heroPriorityImage.addEventListener("load", finish, { once: true });
      heroPriorityImage.addEventListener("error", resolve, { once: true });
    }
  });
  return Promise.race([imageReady, new Promise((resolve) => setTimeout(resolve, 2500))]);
})();

function runAfterHeroCritical(callback, urgent = false) {
  const run = () => {
    if (!urgent && "requestIdleCallback" in window) requestIdleCallback(callback, { timeout: 600 });
    else setTimeout(callback, 0);
  };
  if (urgent || heroPriorityImage?.complete) run();
  else heroCriticalReady.finally(run);
}

function observeBeforeEnter(target, callback, rootMargin = "1200px 0px") {
  if (!target) return;
  if (!("IntersectionObserver" in window)) {
    runAfterHeroCritical(callback);
    return;
  }
  const observer = new IntersectionObserver(([entry]) => {
    if (!entry?.isIntersecting) return;
    observer.disconnect();
    runAfterHeroCritical(callback);
  }, { rootMargin, threshold: 0 });
  observer.observe(target);
}

function activateDeferredImage(image, priority = "low", shouldDecode = false) {
  if (!image) return Promise.resolve();
  image.decoding = "async";
  image.fetchPriority = priority;
  const source = image.dataset.src;
  if (source && !image.hasAttribute("src")) {
    image.loading = "eager";
    image.src = source;
  }
  if (!shouldDecode || typeof image.decode !== "function") return Promise.resolve();
  return image.decode().catch(() => undefined);
}
