function getEasterMotion(product) {
  const id = product.id || "";
  if (id.includes("hanging-") || id.includes("clover-ornament")) return "sway-hanging";
  if (id.includes("flowers") || id.includes("sprig")) return "sway-foliage";
  if (id.includes("planter")) return "breathe-soft";
  if (id.includes("painted-eggs") || id.includes("single-egg")) return "rock-soft";
  if (id.includes("basket")) return "bob-soft";
  if (id.includes("tiered-eggs") || id.includes("clover") || id.includes("frame")) return "pulse-soft";
  if (id.includes("rabbit")) {
    if (id.includes("mini-rabbit")) return "hop-soft";
    if (id.includes("rabbit-upper-left") || id.includes("rabbit-centre")) return "nod-soft";
  }
  return "breathe-soft";
}

const easterRearMainPlaneProducts = new Set([
  "easter-regenerated-basket-upper-centre",
  "easter-regenerated-frame-centre",
  "easter-regenerated-tiered-eggs-centre",
  "easter-regenerated-rabbit-centre",
  "easter-regenerated-mini-rabbit-left"
]);

const easterRearFarPlaneProducts = new Set([
  "easter-regenerated-flowers-far-right",
  "easter-regenerated-painted-eggs-far-right",
  "easter-regenerated-mini-rabbit-far-right"
]);

const easterFrontMidPlaneProducts = new Set([
  "easter-regenerated-flowers-upper-left",
  "easter-regenerated-flower-sprig-upper-left",
  "easter-regenerated-planter-upper-left",
  "easter-regenerated-tiered-eggs-upper-left",
  "easter-regenerated-rabbit-upper-left",
  "easter-regenerated-clover-plaques-left",
  "easter-regenerated-single-egg-left"
]);

function getEasterDepthGroup(product) {
  const id = product.id || "";
  if (product.depthGroup) return product.depthGroup;
  if (id.includes("hanging-") || id.includes("clover-ornament")) return "hanging";
  if (easterRearFarPlaneProducts.has(id)) return "rear-far";
  if (easterRearMainPlaneProducts.has(id)) return "rear-main";
  if (easterFrontMidPlaneProducts.has(id)) return "front-mid";
  return "front-near";
}

async function createHomeProductHotspots() {
  const layer = document.querySelector("#home-product-hotspots");
  if (!layer || layer.childElementCount) return;
  try {
    let scene = window.LANDY_HOME_SCENE;
    layer.dataset.sceneSource = scene ? "script" : "fetch";
    if (!scene) {
      const response = await fetch("journey-interactive/home/scene.json?v=20260818j");
      if (!response.ok) throw new Error(`Home scene failed to load (${response.status})`);
      scene = await response.json();
    }
    homeProductSpots = Array.isArray(scene.products) ? scene.products : [];
  } catch (error) {
    console.error(error);
    homeProductSpots = [];
    return;
  }
  const productPlanes = new Map(["wall", "hanging", "rear-cabinets", "sofa-left", "road-front"].map((depthGroup) => {
    const plane = document.createElement("div");
    plane.className = "journey-product-plane";
    plane.dataset.depthGroup = depthGroup;
    layer.appendChild(plane);
    return [depthGroup, plane];
  }));
  homeProductSpots.forEach((spot, index) => {
    const product = document.createElement("span");
    product.className = `journey-product-hotspot has-independent-asset animation-${spot.animation || "breathe-soft"}`;
    product.dataset.category = spot.category;
    product.dataset.productId = spot.id;
    product.dataset.depthGroup = spot.depthGroup || "rear-cabinets";
    product.style.setProperty("--spot-x", spot.x);
    product.style.setProperty("--spot-y", spot.y);
    product.style.setProperty("--spot-w", spot.width);
    product.style.setProperty("--spot-h", spot.height);
    product.style.zIndex = spot.zIndex || 6;
    product.style.setProperty("--spot-accent", ["#a76543", "#6c8494", "#c98b62", "#748677"][index % 4]);
    product.style.setProperty("--breathe-delay", `${-(index % 6) * .61}s`);
    product.innerHTML = `<span class="journey-product-cutout"><img data-src="journey-interactive/${spot.asset}?v=20260810d" alt="" loading="lazy" decoding="async" fetchpriority="low" /></span>`;
    product.setAttribute("aria-label", localizedSceneName(spot));
    product.setAttribute("role", "img");
    productPlanes.get(product.dataset.depthGroup)?.appendChild(product);
  });
}

