  christmasProductSpots.forEach((spot,index)=>{const p=document.createElement("span");const key=spot.id.replace("christmas-","");const n=names[key]||[key.replaceAll("-"," "),key.replaceAll("-"," ")];p.className="journey-product-hotspot has-independent-asset animation-breathe-soft";p.dataset.category=spot.category;p.dataset.productId=spot.id;p.style.setProperty("--spot-x",spot.x/16.72);p.style.setProperty("--spot-y",spot.y/9.41);p.style.setProperty("--spot-w",spot.width/16.72);p.style.setProperty("--spot-h",spot.height/9.41);p.style.zIndex=spot.zIndex;p.innerHTML=`<span class="journey-product-cutout"><img data-src="journey-interactive/christmas/products-v1/${spot.asset}?v=20260817w" alt="" loading="lazy" decoding="async" fetchpriority="low" /></span>`;p.setAttribute("aria-label",isChineseLanguage()?localizeChinese(n[1]):n[0]);p.setAttribute("role","img");planes.get(spot.depthGroup)?.appendChild(p)});
