/* Keep decoded image memory bounded. The active story and its immediate
   neighbours are warmed in advance; product images farther away retain only
   their URL until the camera approaches them. */
let journeyRenderWindowIndex = -1;
let journeyPrewarmIndex = -1;
let journeyAssetMaintenanceTimer = 0;
const journeyDecodePromises = new WeakMap();

function decodeJourneyImage(image) {
  if (!image || journeyDecodePromises.has(image)) return journeyDecodePromises.get(image);
  const decodePromise = typeof image.decode === "function"
    ? image.decode().catch(() => undefined)
    : Promise.resolve();
  journeyDecodePromises.set(image, decodePromise);
  return decodePromise;
}

function warmJourneyPanelShell(index, priority = "low", shouldDecode = false) {
  const panel = journeyPanels[index];
  if (!panel) return Promise.resolve();
  const shellImages = [...panel.querySelectorAll(".journey-depth-layer[data-src]")];
  const readyPromise = Promise.all(shellImages.map((image) => {
    activateDeferredImage(image, priority);
    return shouldDecode ? decodeJourneyImage(image) : Promise.resolve();
  })).then(() => {
    panel.dataset.shellReady = "true";
  });
  return readyPromise;
}

function warmJourneyPanel(index, priority = "low", shouldDecode = false) {
  const panel = journeyPanels[index];
  if (!panel) return;
  warmJourneyPanelShell(index, priority, shouldDecode);
  panel.querySelectorAll("img").forEach((image) => {
    activateDeferredImage(image, priority);
    if (shouldDecode) decodeJourneyImage(image);
  });
  panel.dataset.assetState = "warm";
}

function coolJourneyPanel(index) {
  const panel = journeyPanels[index];
  if (!panel) return;
  if (panel.dataset.assetState === "cold" && !panel.querySelector("img[data-src][src]")) return;
  panel.querySelectorAll("img[data-src][src]").forEach((image) => {
    image.removeAttribute("src");
    image.loading = "lazy";
    image.fetchPriority = "low";
    journeyDecodePromises.delete(image);
  });
  delete panel.dataset.shellReady;
  panel.dataset.assetState = "cold";
}

function maintainJourneyPanelAssets(index) {
  const near = new Set([index - 1, index, index + 1, index + 2].filter((value) => value >= 0 && value < journeyPanels.length));
  journeyPanels.forEach((panel, panelIndex) => {
    const shouldRender = near.has(panelIndex);
    if (shouldRender) warmJourneyPanel(panelIndex, panelIndex === index && journeyRuntimeActive ? "auto" : "low", panelIndex === index && journeyRuntimeActive);
    else if (panelIndex !== journeyPrewarmIndex) coolJourneyPanel(panelIndex);
  });
  if (journeyPrewarmIndex >= 0) warmJourneyPanel(journeyPrewarmIndex, "auto", journeyRuntimeActive);
}

function syncJourneyPanelMounts(index) {
  if (!journeyPanelMountingReady || !journeyMap) return;
  const near = new Set([index - 1, index, index + 1].filter((value) => value >= 0 && value < journeyPanels.length));
  journeyPanels.forEach((panel, panelIndex) => {
    const shouldMount = near.has(panelIndex);
    if (shouldMount && !panel.isConnected) {
      journeyMap.insertBefore(panel, journeyPanelSlots[panelIndex]);
    } else if (!shouldMount && panel.isConnected) {
      panel.remove();
    }
  });
}

function updateJourneyRenderWindow(index) {
  if (!Number.isInteger(index) || index === journeyRenderWindowIndex) return;
  const initialWindow = journeyRenderWindowIndex < 0;
  journeyRenderWindowIndex = index;
  const near = new Set([index - 1, index, index + 1].filter((value) => value >= 0 && value < journeyPanels.length));
  journeyPanels.forEach((panel, panelIndex) => {
    panel.classList.toggle("is-render-near", near.has(panelIndex));
  });
  syncJourneyPanelMounts(index);
  if (index === journeyPrewarmIndex) journeyPrewarmIndex = -1;
  clearTimeout(journeyAssetMaintenanceTimer);
  if (initialWindow) maintainJourneyPanelAssets(index);
  else {
    /* Loading the next chapter and releasing the old one during the exact
       camera handoff caused a visible hitch. Do that work just after the
       boundary instead, while the new chapter is dwelling. */
    journeyAssetMaintenanceTimer = setTimeout(() => {
      if (journeyRenderWindowIndex === index) maintainJourneyPanelAssets(index);
    }, 60);
  }
}

let warmDesktopJourneyStart = () => {};
if (!journeyMobileMode) {
  journeyVisual?.classList.add("is-windowed");
  warmDesktopJourneyStart = () => {
    if (journeyRenderWindowIndex < 0) updateJourneyRenderWindow(0);
    else maintainJourneyPanelAssets(journeyRenderWindowIndex);
  };
  observeBeforeEnter(journey, warmDesktopJourneyStart);
}

/* Product hotspots arrive asynchronously from the scene data files. Apply
   the same warm/cold policy to images added after the initial render pass. */
if (!journeyMobileMode && journeyMap && "MutationObserver" in window) {
  const journeyAssetObserver = new MutationObserver((mutations) => {
    const touchedPanels = new Set();
    mutations.forEach((mutation) => mutation.addedNodes.forEach((node) => {
      if (!(node instanceof Element)) return;
      const images = node.matches("img") ? [node] : [...node.querySelectorAll("img")];
      images.forEach((image) => {
        const panel = image.closest(".journey-panel");
        image.decoding = "async";
        if (panel?.classList.contains("is-render-near")) touchedPanels.add(panel);
        else if (image.dataset.src) image.removeAttribute("src");
      });
    }));
    touchedPanels.forEach((panel) => {
      const panelIndex = journeyPanels.indexOf(panel);
      const isCurrent = panelIndex === journeyRenderWindowIndex && journeyRuntimeActive;
      warmJourneyPanel(panelIndex, isCurrent ? "auto" : "low", isCurrent);
    });
  });
  journeyAssetObserver.observe(journeyMap, { childList: true, subtree: true });
}

const journeyPanelSpotCache = new WeakMap();
let journeyFocusPanel = null;
let journeyFocusKey = "";
let journeyFocusFrame = 0;
let pendingJourneyFocus = null;

function getJourneyPanelSpots(panel) {
  if (!panel) return [];
  if (!journeyPanelSpotCache.has(panel)) {
    journeyPanelSpotCache.set(panel, [...panel.querySelectorAll(".journey-product-hotspot")]);
  }
  return journeyPanelSpotCache.get(panel);
}

function clearJourneyPanelFocus(panel) {
  if (!panel) return;
  panel.classList.remove("has-product-focus");
  getJourneyPanelSpots(panel).forEach((spot) => {
    spot.classList.remove("is-category-active", "is-muted");
  });
}

function applyJourneyProductFocus(category, { preview = false, productId = null } = {}) {
  const activeCategory = category || null;
  const activePanel = activeCategory ? journeyPanels[journeyIndex] : null;
  const nextKey = activePanel ? `${journeyIndex}:${activeCategory}:${productId || "*"}:${preview ? 1 : 0}` : "";
  if (activePanel === journeyFocusPanel && nextKey === journeyFocusKey) return;

  /* Moving between products in the same dense scene only needs one final
     class pass. Clearing all 30–61 hotspots first doubled DOM/style work on
     every boundary crossing in Thanksgiving and Christmas. */
  if (activePanel !== journeyFocusPanel) clearJourneyPanelFocus(journeyFocusPanel);
  journeyTags?.querySelectorAll("[data-journey-category]").forEach((button) => {
    button.classList.remove("is-preview");
  });

  journeyFocusPanel = activePanel;
  journeyFocusKey = nextKey;
  if (!activePanel) return;

  const isSingleProduct = Boolean(productId);
  activePanel.classList.add("has-product-focus");
  getJourneyPanelSpots(activePanel).forEach((spot) => {
    const matches = isSingleProduct
      ? spot.dataset.productId === productId
      : spot.dataset.category === activeCategory;
    spot.classList.toggle("is-category-active", matches);
    spot.classList.toggle("is-muted", !matches);
  });
  journeyTags?.querySelectorAll("[data-journey-category]").forEach((button) => {
    button.classList.toggle("is-preview", preview && button.dataset.journeyCategory === activeCategory);
  });
}

function scheduleJourneyProductFocus(category, options = {}) {
  pendingJourneyFocus = { category, options };
  if (journeyFocusFrame) return;
  journeyFocusFrame = requestAnimationFrame(() => {
    journeyFocusFrame = 0;
    const request = pendingJourneyFocus;
    pendingJourneyFocus = null;
    if (request) applyJourneyProductFocus(request.category, request.options);
  });
}

function cancelScheduledJourneyProductFocus() {
  if (journeyFocusFrame) cancelAnimationFrame(journeyFocusFrame);
  journeyFocusFrame = 0;
  pendingJourneyFocus = null;
}

function measureJourneyGeometry() {
  if (!journeyPanelPaths.length || !journeyVisual) return null;
  const routeSvg = journeyPanelPaths[0].ownerSVGElement;
  const vb = routeSvg.viewBox.baseVal;
  const viewportWidth = journeyVisual.clientWidth;
  const viewportHeight = journeyVisual.clientHeight;
  const scale = Math.max(viewportWidth / vb.width, viewportHeight / vb.height);
  const mediaWidth = vb.width * scale;
  const mediaHeight = vb.height * scale;
  const mediaX = (viewportWidth - mediaWidth) * 0.5;
  const mediaY = (viewportHeight - mediaHeight) * 0.5;
  const pathLengths = journeyPanelPaths.map((path) => path.getTotalLength());
  const geometry = {
    pathLengths,
    totalPathLength: pathLengths.reduce((total, length) => total + length, 0),
    viewBoxWidth: vb.width,
    viewBoxHeight: vb.height,
    viewportWidth,
    viewportHeight,
    scale,
    mediaWidth,
    mediaHeight,
    mediaX,
    mediaY
  };
  if (!geometry.totalPathLength || !geometry.viewBoxWidth || !geometry.viewBoxHeight ||
      !geometry.viewportWidth || !geometry.viewportHeight) return null;
  journeyPanels.forEach((panel) => {
    panel.style.setProperty("--panel-media-width", `${mediaWidth.toFixed(2)}px`);
    panel.style.setProperty("--panel-media-height", `${mediaHeight.toFixed(2)}px`);
    panel.style.setProperty("--panel-media-x", `${mediaX.toFixed(2)}px`);
    panel.style.setProperty("--panel-media-y", `${mediaY.toFixed(2)}px`);
  });
  journeyGeometry = geometry;
  return geometry;
}

function setJourneyScene(index) {
  if (!journey || index === journeyIndex) return;
  cancelScheduledJourneyProductFocus();
  const previousIndex = journeyIndex;
  applyJourneyProductFocus(null);
  journeyIndex = index;
  /* Prepare the incoming scene in one hidden-frame style batch. Letting the
     outgoing parallax ease back over many frames kept doing work after it was
     invisible and competed with the curtain animation. */
  if (previousIndex >= 0 && previousIndex !== index) settleJourneyParallaxImmediately(previousIndex);
  const item = journeyData[index];
  const langIndex = isChineseLanguage() ? 1 : 0;
  journeyMonth.textContent = localizeChinese(item.month[langIndex]);
  journeyTitle.textContent = localizeChinese(item.title[langIndex]);
  journeyDesc.textContent = localizeChinese(item.desc[langIndex]);
  journey.style.setProperty("--scene-wash", item.wash);
  journey.dataset.sceneActive = String(index);
  /* Compact desktop/tablet layouts keep one stable composition. Swapping the
     copy between opposite sides reads as a horizontal page jump on iPad. */
  journey.dataset.cardSide = window.innerWidth <= 1366
    ? "left"
    : journeyCardSides[index] || "left";
  journeyTags.innerHTML = item.tags.map((tag) => {
    const label = isChineseLanguage() ? localizeChinese(journeyTagZh.get(tag) || tag) : tag;
    const category = index === 0
      ? homeCategoryIds.get(tag)
      : index === 1
        ? valentineCategoryIds.get(tag)
        : index === 2
          ? easterCategoryIds.get(tag)
          : index === 3
            ? gardenCategoryIds.get(tag)
            : index === 4
              ? coastlineCategoryIds.get(tag)
              : index === 5
                ? farmhouseCategoryIds.get(tag)
                : index === 6
                  ? halloweenCategoryIds.get(tag)
                  : index === 7
                    ? thanksgivingCategoryIds.get(tag)
                    : christmasCategoryIds.get(tag);
    return category
      ? `<button type="button" class="journey-category-tag" data-journey-category="${category}">${label}</button>`
      : `<span>${label}</span>`;
  }).join("");
  journeyStep.textContent = String(index + 1).padStart(2, "0");
  journeyTraveler?.style.setProperty("--voyager-accent", journeyAccents[index]);
  journey.style.setProperty("--journey-route-accent", journeyAccents[index]);
  if (voyagerCharm) {
    voyagerCharm.textContent = journeyCharms[index];
    voyagerCharm.style.transform = "translate(-50%,-50%) scale(.72)";
    requestAnimationFrame(() => { voyagerCharm.style.transform = "translate(-50%,-50%) scale(1)"; });
  }
  voyagerDots.forEach((dot, i) => dot.classList.toggle("complete", i <= index));
  journeyRailDots.forEach((dot, i) => {
    dot.classList.toggle("complete", i <= index);
    dot.classList.toggle("active", i === index);
    dot.setAttribute("aria-label", journeyData[i].title[langIndex]);
    if (i === index) dot.setAttribute("aria-current", "step");
    else dot.removeAttribute("aria-current");
  });
  if (previousIndex < 0) {
    journeyPanels.forEach((panel, panelIndex) => {
      panel.setAttribute("aria-hidden", String(panelIndex !== index));
    });
  } else {
    journeyPanels[previousIndex]?.setAttribute("aria-hidden", "true");
    journeyPanels[index]?.setAttribute("aria-hidden", "false");
  }
  /* Accessibility labels do not affect the visual handoff. Move their dense
     DOM pass out of the curtain frame, especially for the 61-item Christmas
     chapter, so the opacity animation remains compositor-only. */
  clearTimeout(journeySceneMaintenanceTimer);
  journeySceneMaintenanceTimer = setTimeout(() => {
    if (journeyIndex !== index) return;
    const activeJourneyPanel = journeyPanels[index];
    if (index >= 0 && index <= 8 && activeJourneyPanel?.dataset.labelLang !== currentLang) {
      const sceneProducts = index === 0 ? homeProductSpots
        : index === 1 ? valentineProductSpots
        : index === 2 ? easterProductSpots
        : index === 3 ? gardenProductSpots
        : index === 4 ? coastlineProductSpots
        : index === 5 ? farmhouseProductSpots
        : index === 6 ? halloweenProductSpots
        : index === 7 ? thanksgivingProductSpots
        : christmasProductSpots;
      const productsById = new Map(sceneProducts.map((product) => [product.id, product]));
      activeJourneyPanel.querySelectorAll(".journey-product-hotspot").forEach((spot) => {
        const product = productsById.get(spot.dataset.productId);
        if (product) spot.setAttribute("aria-label", langIndex ? localizeChinese(product.name_zh) : product.name_en);
      });
      activeJourneyPanel.dataset.labelLang = currentLang;
    }
    journeyExplore.firstChild.textContent = isChineseLanguage() ? localizeChinese("在展厅查看该系列 ") : "Explore this collection ";
  }, 360);
}

function updateJourney() {
  if (!journeySpace || !journeyPanelPaths.length || !journeyTraveler || !journeyVisual || !journeyMap) return;
  const geometry = journeyGeometry || measureJourneyGeometry();
  if (!geometry) return;
  const {
    pathLengths,
    viewportWidth, viewportHeight, scale, mediaWidth, mediaX, mediaY
  } = geometry;

  const rect = journeySpace.getBoundingClientRect();
  const travel = Math.max(1, rect.height - window.innerHeight);
  const progress = Math.max(0, Math.min(1, -rect.top / travel));
  journey.style.setProperty("--journey-progress", progress.toFixed(4));

  /*
   * Give every story exactly the same scroll budget, regardless of its SVG
   * path length. The traveler advances continuously for the full chapter,
   * while the camera holds the complete scene for 68% and uses the final 32%
   * for a smooth handoff to the next full-frame scene.
   */
  const sceneCount = journeyData.length;
  const scaledProgress = Math.min(sceneCount - Number.EPSILON, progress * sceneCount);
  const scrollSceneIndex = Math.min(sceneCount - 1, Math.floor(scaledProgress));
  const sceneProgress = scaledProgress - scrollSceneIndex;
  const dwellEnd = 0.68;
  let handoffProgress = 0;
  let motionPhase = "viewing";
  const smooth01 = (value) => {
    const clamped = Math.max(0, Math.min(1, value));
    return clamped * clamped * (3 - 2 * clamped);
  };
  if (sceneProgress <= dwellEnd) {
    motionPhase = "viewing";
  } else {
    handoffProgress = (sceneProgress - dwellEnd) / (1 - dwellEnd);
    motionPhase = "handoff";
  }
  setJourneyDataset("motionPhase", motionPhase);
  setJourneyDataset("scrollScene", String(scrollSceneIndex));
  journey.style.setProperty("--journey-scene-progress", sceneProgress.toFixed(4));
  updateJourneyRenderWindow(scrollSceneIndex);

  const segmentIndex = scrollSceneIndex;
  const segmentStart = pathLengths
    .slice(0, segmentIndex)
    .reduce((sum, length) => sum + length, 0);
  const segmentLength = pathLengths[segmentIndex];
  /* Reach the visible road endpoint before the vertical page handoff begins. */
  const routeProgress = Math.min(1, sceneProgress / dwellEnd);
  const traveledLength = segmentStart + segmentLength * routeProgress;
  const segmentDistance = Math.max(0, Math.min(segmentLength, traveledLength - segmentStart));
  const segmentProgress = segmentLength ? segmentDistance / segmentLength : 0;
  const journeyPath = journeyPanelPaths[segmentIndex];
  const point = journeyPath.getPointAtLength(segmentDistance);
  const next = journeyPath.getPointAtLength(Math.min(segmentLength, segmentDistance + 4));
  const lookAhead = journeyPath.getPointAtLength(Math.min(segmentLength, segmentDistance + 72));

  journeyPanelPaths.forEach((path, index) => {
    const pathProgress = index < segmentIndex ? 1 : index === segmentIndex ? segmentProgress : 0;
    if (Math.abs(journeyPathProgressCache[index] - pathProgress) < .0005) return;
    journeyPathProgressCache[index] = pathProgress;
    path.style.setProperty("--segment-progress", pathProgress.toFixed(4));
    /*
     * The route uses a non-scaling stroke, so dash lengths are interpreted in
     * rendered CSS pixels rather than the SVG's native viewBox units.
     */
    const renderedPathLength = pathLengths[index] * scale;
    path.style.strokeDasharray = `${(renderedPathLength * pathProgress).toFixed(3)} ${renderedPathLength.toFixed(3)}`;
    path.style.strokeDashoffset = "0";
  });

  const nextSceneIndex = Math.min(sceneCount - 1, scrollSceneIndex + 1);
  const hasInternalHandoff = motionPhase === "handoff" && nextSceneIndex !== scrollSceneIndex;
  /* Keep the scene legible even when a gesture stops at the exact handoff
     midpoint. The old fully opaque plateau looked like a loading screen and
     required a synthetic scroll nudge to escape it. */
  const curtainOpacity = !hasInternalHandoff
    ? 0
    : Math.sin(Math.PI * handoffProgress) * 0.58;
  const cardOpacity = !hasInternalHandoff
    ? 1
    : handoffProgress < 0.5
      ? 1 - smooth01(handoffProgress / 0.42)
      : smooth01((handoffProgress - 0.58) / 0.34);
  journey.style.setProperty("--card-opacity", cardOpacity.toFixed(3));
  journey.style.setProperty("--card-offset", `${((1 - cardOpacity) * 18).toFixed(1)}px`);
  journey.style.setProperty("--journey-curtain-opacity", curtainOpacity.toFixed(3));

  /*
   * Image and route share one coordinate system. Move the complete panorama
   * as one continuous paper world; the traveler is then placed at the exact
   * screen-space projection of the sampled road centre.
   */
  const compactJourney = viewportWidth <= 900;
  const stableHorizontalJourney = viewportWidth <= 1366;
  const naturalX = mediaX + point.x * scale;
  const needsHorizontalCamera = mediaWidth > viewportWidth + 1;
  const roadDirection = Math.max(-1, Math.min(1, (lookAhead.x - point.x) / 90));
  const cameraLead = roadDirection * viewportWidth * (compactJourney ? 0.025 : 0.04);
  const desiredX = needsHorizontalCamera
    ? Math.max(
        viewportWidth * (compactJourney ? 0.25 : 0.30),
        Math.min(
          viewportWidth * (compactJourney ? 0.75 : 0.70),
          viewportWidth * 0.5 + cameraLead
        )
      )
    : naturalX;
  const unclampedPanoramaX = needsHorizontalCamera ? desiredX - naturalX : 0;
  const minimumPanoramaX = viewportWidth - (mediaX + mediaWidth);
  const maximumPanoramaX = -mediaX;
  const panoramaX = stableHorizontalJourney
    ? 0
    : needsHorizontalCamera
      ? Math.max(minimumPanoramaX, Math.min(maximumPanoramaX, unclampedPanoramaX))
      : 0;
  let travelerX = naturalX + panoramaX;

  /* Swap chapters only while the opaque paper curtain covers the stage. */
  const visualSceneIndex = hasInternalHandoff && handoffProgress >= 0.5
    ? nextSceneIndex
    : scrollSceneIndex;
  const sceneSettleY = !hasInternalHandoff
    ? 0
    : handoffProgress < 0.5
      ? -4 * smooth01(handoffProgress / 0.5)
      : 10 * (1 - smooth01((handoffProgress - 0.5) / 0.5));
  const localTravelerY = mediaY + point.y * scale;
  let travelerY = localTravelerY;
  let travelerOpacity = 1;

  if (motionPhase === "viewing") {
    /* Let the gift enter below the fixed header, then settle onto the path. */
    travelerY += 105 * (1 - smooth01(sceneProgress / 0.14));
  }

  if (hasInternalHandoff) {
    if (handoffProgress < 0.5) {
      travelerY = localTravelerY + 16 * smooth01(handoffProgress / 0.5);
      travelerOpacity = 1 - smooth01((handoffProgress - 0.08) / 0.34);
    } else {
      const nextPath = journeyPanelPaths[nextSceneIndex];
      const nextPoint = nextPath.getPointAtLength(0);
      const entryProgress = smooth01((handoffProgress - 0.58) / 0.34);
      travelerX = mediaX + nextPoint.x * scale + panoramaX;
      travelerY = mediaY + nextPoint.y * scale + 105 + 12 * (1 - entryProgress);
      travelerOpacity = entryProgress;
    }
  }
  journey.style.setProperty("--panorama-x", `${panoramaX.toFixed(2)}px`);
  journey.style.setProperty("--scene-settle-y", `${sceneSettleY.toFixed(2)}px`);
  journeyTraveler.style.setProperty("--voyager-x", `${travelerX.toFixed(2)}px`);
  journeyTraveler.style.setProperty("--voyager-y", `${travelerY.toFixed(2)}px`);
  journeyTraveler.style.opacity = travelerOpacity.toFixed(3);

  const rawAngle = Math.atan2(next.y - point.y, next.x - point.x) * 180 / Math.PI;
  const facing = Math.cos(rawAngle * Math.PI / 180) < 0 ? -1 : 1;
  let tilt = facing < 0 ? rawAngle - 180 : rawAngle;
  if (tilt > 90) tilt -= 180;
  if (tilt < -90) tilt += 180;
  /* Keep the gift mark upright; the emblem supplies its own gentle sway. */
  tilt = Math.max(-2.5, Math.min(2.5, tilt * .24));

  voyagerFacing?.style.setProperty("--voyager-facing", String(facing));
  voyagerFacing?.style.setProperty("--voyager-tilt", `${tilt.toFixed(2)}deg`);
  setJourneyScene(visualSceneIndex);
  /* Keep interface anchors stable while the illustrated world moves. */
  setJourneyDataset("cardSide", stableHorizontalJourney ? "left" : journeyCardSides[visualSceneIndex] || "left");
  setJourneyDataset("railSide", "right");
}

let journeyTicking = false;
let journeyUpdateFrame = 0;
let journeyStopTimer;
function scheduleJourneyUpdate() {
  if (!journeyRuntimeActive || journeyTicking) return;
  journeyTicking = true;
  journeyUpdateFrame = requestAnimationFrame(() => {
    journeyUpdateFrame = 0;
    updateJourney();
    journeyTicking = false;
  });
}
function scheduleJourneyMeasure() {
  journeyGeometry = null;
  scheduleJourneyUpdate();
}

window.addEventListener("scroll", () => {
  if (!journeyRuntimeActive) return;
  journey?.classList.add("is-moving");
  clearTimeout(journeyStopTimer);
  journeyStopTimer = setTimeout(() => journey?.classList.remove("is-moving"), 170);
  scheduleJourneyUpdate();
}, { passive: true });
window.addEventListener("resize", scheduleJourneyMeasure);
journeyMap?.querySelectorAll("img").forEach((image) => {
  if (!image.complete) image.addEventListener("load", scheduleJourneyMeasure, { once: true });
});
if ("ResizeObserver" in window && journeyVisual) {
  const journeyResizeObserver = new ResizeObserver(scheduleJourneyMeasure);
  journeyResizeObserver.observe(journeyVisual);
}
journeyExplore?.addEventListener("click", () => {
  const item = journeyData[Math.max(0, journeyIndex)];
  runAfterHeroCritical(warmGalleryFirstPage, true);
  document.querySelector("#product-gallery")?.scrollIntoView({ behavior: "smooth", block: "start" });
  setTimeout(() => {
    if (subcategoryFilter && [...subcategoryFilter.options].some(option => option.value === item.filter)) {
      subcategoryFilter.value = item.filter;
      subcategoryFilter.dispatchEvent(new Event("change", { bubbles: true }));
    } else if (categoryFilter && item.filter === "Home Decor") {
      categoryFilter.value = "Home Decor";
      categoryFilter.dispatchEvent(new Event("change", { bubbles: true }));
    }
  }, 650);
});

function scrollJourneyTo(index) {
  if (!journeySpace || !journeyData[index]) return;
  /* Navigation jumps may cross several chapters quickly, so decode the
     destination products before the smooth camera movement reaches them. */
  journeyPrewarmIndex = index;
  warmJourneyPanel(index, "auto", true);
  /* Land every navigation jump inside the equal-length viewing plateau. */
  const progress = (index + 0.32) / journeyData.length;
  const rect = journeySpace.getBoundingClientRect();
  const spaceTop = window.scrollY + rect.top;
  const travel = Math.max(1, rect.height - window.innerHeight);
  window.scrollTo({
    top: spaceTop + travel * progress,
    behavior: window.matchMedia("(prefers-reduced-motion: reduce)").matches ? "auto" : "smooth"
  });
}

journeyRailDots.forEach((dot, index) => {
  dot.addEventListener("click", () => scrollJourneyTo(index));
  dot.addEventListener("keydown", (event) => {
    const previous = event.key === "ArrowUp" || event.key === "ArrowLeft";
    const next = event.key === "ArrowDown" || event.key === "ArrowRight";
    if (!previous && !next) return;
    event.preventDefault();
    const targetIndex = Math.max(0, Math.min(journeyRailDots.length - 1, index + (next ? 1 : -1)));
    journeyRailDots[targetIndex]?.focus();
    scrollJourneyTo(targetIndex);
  });
});

