const easterParallaxAllowed = !journeyConstrainedDevice && window.matchMedia("(pointer:fine)").matches &&
  !window.matchMedia("(prefers-reduced-motion:reduce)").matches;
let easterParallaxFrame = 0;
let easterParallaxTargetX = 0;
let easterParallaxTargetY = 0;
let easterParallaxCurrentX = 0;
let easterParallaxCurrentY = 0;

function renderEasterParallax() {
  easterParallaxFrame = 0;
  easterParallaxCurrentX += (easterParallaxTargetX - easterParallaxCurrentX) * .14;
  easterParallaxCurrentY += (easterParallaxTargetY - easterParallaxCurrentY) * .14;
  /*
   * The road and near hill have the least hidden overlap in the top-right
   * direction. Ease only the final part of that quadrant so their masks stay
   * inside the clean bleed while every other direction keeps full depth.
   */
  const topRightStress = Math.min(1,
    Math.max(0,easterParallaxCurrentX) * Math.max(0,-easterParallaxCurrentY) * 2.3
  );
  const terrainSafety = 1 - topRightStress * .16;
  const terrainX = easterParallaxCurrentX * terrainSafety;
  const terrainY = easterParallaxCurrentY * terrainSafety;
  easterInteractivePanel?.style.setProperty("--easter-sky-x", `${(-terrainX * 7).toFixed(2)}px`);
  easterInteractivePanel?.style.setProperty("--easter-sky-y", `${(-terrainY * 4).toFixed(2)}px`);
  easterInteractivePanel?.style.setProperty("--easter-rear-backstop-x", `${(-terrainX * 18).toFixed(2)}px`);
  easterInteractivePanel?.style.setProperty("--easter-rear-backstop-y", `${(-terrainY * 10).toFixed(2)}px`);
  easterInteractivePanel?.style.setProperty("--easter-rear-far-x", `${(-terrainX * 13).toFixed(2)}px`);
  easterInteractivePanel?.style.setProperty("--easter-rear-far-y", `${(-terrainY * 7).toFixed(2)}px`);
  easterInteractivePanel?.style.setProperty("--easter-rear-main-x", `${(-terrainX * 22).toFixed(2)}px`);
  easterInteractivePanel?.style.setProperty("--easter-rear-main-y", `${(-terrainY * 12).toFixed(2)}px`);
  easterInteractivePanel?.style.setProperty("--easter-road-x", `${(-terrainX * 34).toFixed(2)}px`);
  easterInteractivePanel?.style.setProperty("--easter-road-y", `${(-terrainY * 18).toFixed(2)}px`);
  easterInteractivePanel?.style.setProperty("--easter-front-mid-x", `${(-terrainX * 50).toFixed(2)}px`);
  easterInteractivePanel?.style.setProperty("--easter-front-mid-y", `${(-terrainY * 27).toFixed(2)}px`);
  easterInteractivePanel?.style.setProperty("--easter-front-near-x", `${(-terrainX * 68).toFixed(2)}px`);
  easterInteractivePanel?.style.setProperty("--easter-front-near-y", `${(-terrainY * 37).toFixed(2)}px`);
  easterInteractivePanel?.style.setProperty("--easter-hanging-x", `${(-terrainX * 82).toFixed(2)}px`);
  easterInteractivePanel?.style.setProperty("--easter-hanging-y", `${(-terrainY * 44).toFixed(2)}px`);
  journey?.style.setProperty("--easter-editorial-x", `${(-easterParallaxCurrentX * 16).toFixed(2)}px`);
  journey?.style.setProperty("--easter-editorial-y", `${(-easterParallaxCurrentY * 9).toFixed(2)}px`);
  const unsettled = Math.abs(easterParallaxTargetX - easterParallaxCurrentX) > .004 ||
    Math.abs(easterParallaxTargetY - easterParallaxCurrentY) > .004;
  if (unsettled) easterParallaxFrame = requestAnimationFrame(renderEasterParallax);
}

function scheduleEasterParallax() {
  if (!easterParallaxFrame) easterParallaxFrame = requestAnimationFrame(renderEasterParallax);
}

function setEasterParallaxTarget(x, y) {
  /*
   * Use a circular limit instead of clamping both axes independently. At a
   * viewport corner independent clamps produce a 1.414x diagonal excursion,
   * which can pull transparent paper slices beyond their safe bleed.
   */
  const maxMagnitude = .94;
  const magnitude = Math.hypot(x, y);
  const normalizer = magnitude > maxMagnitude ? maxMagnitude / magnitude : 1;
  easterParallaxTargetX = x * normalizer;
  easterParallaxTargetY = y * normalizer;
  scheduleEasterParallax();
}

function resetEasterParallax() {
  setEasterParallaxTarget(0, 0);
}

