/* The soundtrack stays opt-in on a first visit, uses metadata-only preload,
   and remembers the listener's last track and preference on return visits. */
const musicTracks = [
  { title:"Rhapsody in Blue", artist:"George Gershwin", src:"assets/audio/rhapsody-in-blue.mp3" },
  { title:"Deux Arabesques", artist:"Claude Debussy", src:"assets/audio/deux-arabesques.mp3" }
];
const MUSIC_VOLUME = .52;
let musicTrackIndex = 0;
let musicEnabled = localStorage.getItem("landy_music_enabled") === "true";
let musicFadeToken = 0;
let musicIntentToken = 0;
let musicSwitching = false;
let musicAutoFadeStarted = false;
let musicTemporarilySuspended = false;
let musicTapEngaged = false;
let musicCollapseTimer = 0;
let musicVisualCollapseTimer = 0;

const musicUsesTapControls = () => touchOnlyInput.matches || innerWidth <= 900 || (innerWidth <= 1024 && innerHeight > innerWidth);

function setMusicExpanded(expanded,{ autoCollapse = false } = {}) {
  if (!musicPlayer) return;
  clearTimeout(musicCollapseTimer);
  clearTimeout(musicVisualCollapseTimer);
  const beginsCollapse = !expanded && musicPlayer.classList.contains("is-expanded");
  if (beginsCollapse && musicPlayer.classList.contains("uses-tap-controls")) {
    musicPlayer.classList.add("is-collapsing");
    // Commit the hidden text layer before the width transition begins so
    // Safari never lays the title out inside the shrinking circular width.
    void musicPlayer.offsetWidth;
  } else {
    musicPlayer.classList.remove("is-collapsing");
  }
  musicPlayer.classList.toggle("is-expanded",expanded);
  if (beginsCollapse) {
    musicVisualCollapseTimer = setTimeout(() => musicPlayer.classList.remove("is-collapsing"),680);
  }
  musicToggle?.setAttribute("aria-expanded",String(expanded));
  if (expanded && autoCollapse) {
    musicCollapseTimer = setTimeout(() => setMusicExpanded(false),1800);
  }
  syncMusicPlayerLanguage();
}

function keepTapMusicOpen() {
  if (musicUsesTapControls() && musicPlayer?.classList.contains("is-expanded")) {
    setMusicExpanded(true,{ autoCollapse:true });
  }
}

function syncMusicControlMode() {
  if (!musicPlayer) return;
  const usesTap = musicUsesTapControls();
  const changed = musicPlayer.classList.contains("uses-tap-controls") !== usesTap;
  musicPlayer.classList.toggle("uses-tap-controls",usesTap);
  if (changed) setMusicExpanded(false);
  syncMusicPlayerLanguage();
}

function musicText(key) {
  return (translations[currentLang] || translations.en)[key] || translations.en[key] || key;
}

function syncMusicPlayerLanguage() {
  if (!musicPlayer || !backgroundMusic) return;
  const isActuallyPlaying = musicEnabled && !musicTemporarilySuspended && !backgroundMusic.paused;
  const usesTap = musicPlayer.classList.contains("uses-tap-controls");
  const expanded = musicPlayer.classList.contains("is-expanded");
  musicPlayer.setAttribute("aria-label",musicText("music_player"));
  if (musicToggle) {
    musicToggle.setAttribute("aria-expanded",String(expanded));
    musicToggle.setAttribute("aria-label",musicText(usesTap
      ? (expanded ? "music_collapse" : (musicTapEngaged ? "music_expand" : "music_play"))
      : (isActuallyPlaying ? "music_pause" : "music_play")));
    if (usesTap) musicToggle.removeAttribute("aria-pressed");
    else musicToggle.setAttribute("aria-pressed",String(isActuallyPlaying));
  }
  musicPauseButton?.setAttribute("aria-label",musicText(isActuallyPlaying ? "music_pause" : "music_play"));
  musicPauseButton?.setAttribute("aria-pressed",String(isActuallyPlaying));
  musicNext?.setAttribute("aria-label",musicText("music_next"));
  if (musicStatus) {
    musicStatus.textContent = isActuallyPlaying
      ? musicText("music_playing").replace("{title}",musicTracks[musicTrackIndex].title)
      : musicText("music_paused");
  }
}

function updateMusicPlayerState() {
  if (!musicPlayer || !backgroundMusic) return;
  const isActuallyPlaying = musicEnabled && !musicTemporarilySuspended && !backgroundMusic.paused;
  musicPlayer.classList.toggle("is-playing",isActuallyPlaying);
  musicPlayer.classList.toggle("is-awaiting",musicEnabled && (musicTemporarilySuspended || backgroundMusic.paused));
  if (musicTitle) musicTitle.textContent = musicTracks[musicTrackIndex].title;
  syncMusicPlayerLanguage();
}

function updateMusicMediaSession() {
  if (!("mediaSession" in navigator) || !("MediaMetadata" in window)) return;
  const track = musicTracks[musicTrackIndex];
  try {
    navigator.mediaSession.metadata = new MediaMetadata({
      title:track.title,
      artist:track.artist,
      album:"Landy Creative · Background soundtrack"
    });
  } catch (_) {}
}

function loadMusicTrack(index = musicTrackIndex,{ prepareAudio = true } = {}) {
  if (!backgroundMusic) return;
  musicTrackIndex = (index + musicTracks.length) % musicTracks.length;
  const track = musicTracks[musicTrackIndex];
  if (prepareAudio) backgroundMusic.src = track.src;
  else backgroundMusic.removeAttribute("src");
  backgroundMusic.load();
  backgroundMusic.volume = 0;
  musicAutoFadeStarted = false;
  localStorage.setItem("landy_music_track",String(musicTrackIndex));
  updateMusicMediaSession();
  updateMusicPlayerState();
}

function fadeMusicTo(target,duration = 1200) {
  if (!backgroundMusic) return Promise.resolve(false);
  const token = ++musicFadeToken;
  const startVolume = backgroundMusic.volume;
  const delta = target-startVolume;
  const startTime = performance.now();
  return new Promise((resolve) => {
    const stepVolume = (time) => {
      if (token !== musicFadeToken) {
        resolve(false);
        return;
      }
      const progress = Math.min(1,(time-startTime)/Math.max(1,duration));
      const eased = progress < .5 ? 2*progress*progress : 1-Math.pow(-2*progress+2,2)/2;
      backgroundMusic.volume = Math.max(0,Math.min(1,startVolume+delta*eased));
      if (progress < 1) requestAnimationFrame(stepVolume);
      else resolve(true);
    };
    requestAnimationFrame(stepVolume);
  });
}

async function playMusic({ fadeDuration = 1400 } = {}) {
  if (!backgroundMusic) return false;
  const intent = ++musicIntentToken;
  if (!backgroundMusic.getAttribute("src")) loadMusicTrack(musicTrackIndex,{ prepareAudio:true });
  ++musicFadeToken;
  backgroundMusic.volume = 0;
  try {
    await backgroundMusic.play();
  } catch (_) {
    if (intent !== musicIntentToken) return false;
    musicEnabled = false;
    localStorage.setItem("landy_music_enabled","false");
    updateMusicPlayerState();
    return false;
  }
  if (intent !== musicIntentToken) return false;
  musicEnabled = true;
  musicTemporarilySuspended = false;
  localStorage.setItem("landy_music_enabled","true");
  updateMusicPlayerState();
  fadeMusicTo(MUSIC_VOLUME,fadeDuration);
  return true;
}

async function pauseMusic({ remember = true } = {}) {
  if (!backgroundMusic) return;
  const intent = ++musicIntentToken;
  if (remember) {
    musicEnabled = false;
    musicTemporarilySuspended = false;
    localStorage.setItem("landy_music_enabled","false");
  } else {
    musicTemporarilySuspended = true;
  }
  updateMusicPlayerState();
  await fadeMusicTo(0,620);
  if (intent !== musicIntentToken) return;
  backgroundMusic.pause();
  updateMusicPlayerState();
}

async function changeMusicTrack(step = 1,{ play = musicEnabled,skipFade = false } = {}) {
  if (!backgroundMusic || musicSwitching) return;
  const intent = ++musicIntentToken;
  musicSwitching = true;
  const shouldPlay = Boolean(play);
  if (!skipFade && !backgroundMusic.paused) await fadeMusicTo(0,560);
  if (intent !== musicIntentToken) {
    musicSwitching = false;
    return;
  }
  backgroundMusic.pause();
  loadMusicTrack(musicTrackIndex+step,{ prepareAudio:shouldPlay });
  if (shouldPlay) await playMusic({ fadeDuration:1150 });
  musicSwitching = false;
}

if (backgroundMusic && musicPlayer) {
  syncMusicControlMode();
  loadMusicTrack(musicTrackIndex,{ prepareAudio:false });
  musicToggle?.addEventListener("click",() => {
    if (musicUsesTapControls()) {
      if (!musicTapEngaged) {
        musicTapEngaged = true;
        setMusicExpanded(true,{ autoCollapse:true });
        if (showroomVideo && !showroomVideo.paused) showroomVideo.pause();
        if (!musicEnabled || backgroundMusic.paused) playMusic();
        return;
      }
      setMusicExpanded(!musicPlayer.classList.contains("is-expanded"),{ autoCollapse:!musicPlayer.classList.contains("is-expanded") });
      return;
    }
    if (musicTemporarilySuspended && showroomVideo && !showroomVideo.paused) {
      showroomVideo.pause();
      return;
    }
    if (musicEnabled && !backgroundMusic.paused) pauseMusic();
    else playMusic();
  });
  musicPauseButton?.addEventListener("click",() => {
    keepTapMusicOpen();
    if (musicTemporarilySuspended && showroomVideo && !showroomVideo.paused) {
      showroomVideo.pause();
      return;
    }
    if (musicEnabled && !backgroundMusic.paused) pauseMusic();
    else playMusic();
  });
  musicNext?.addEventListener("click",() => {
    keepTapMusicOpen();
    changeMusicTrack(1,{ play:musicEnabled && !backgroundMusic.paused });
  });
  musicPlayer.addEventListener("pointerenter",() => {
    if (!musicUsesTapControls()) setMusicExpanded(true);
  });
  musicPlayer.addEventListener("pointerleave",() => {
    if (!musicUsesTapControls()) setMusicExpanded(false);
  });
  musicPlayer.addEventListener("focusin",() => {
    if (!musicUsesTapControls()) setMusicExpanded(true);
  });
  musicPlayer.addEventListener("focusout",(event) => {
    if (!musicUsesTapControls() && !musicPlayer.contains(event.relatedTarget)) setMusicExpanded(false);
  });
  window.addEventListener("resize",syncMusicControlMode,{ passive:true });
  window.addEventListener("orientationchange",syncMusicControlMode,{ passive:true });
  backgroundMusic.addEventListener("play",updateMusicPlayerState);
  backgroundMusic.addEventListener("pause",updateMusicPlayerState);
  backgroundMusic.addEventListener("timeupdate",() => {
    const remaining = backgroundMusic.duration-backgroundMusic.currentTime;
    if (musicEnabled && !musicAutoFadeStarted && Number.isFinite(remaining) && remaining <= 1.8) {
      musicAutoFadeStarted = true;
      fadeMusicTo(0,Math.max(500,remaining*1000));
    }
  });
  backgroundMusic.addEventListener("ended",() => {
    if (musicEnabled) changeMusicTrack(1,{ play:true,skipFade:true });
  });
  backgroundMusic.addEventListener("error",() => {
    if (!musicSwitching) {
      musicEnabled = false;
      localStorage.setItem("landy_music_enabled","false");
      updateMusicPlayerState();
    }
  });
  if ("mediaSession" in navigator) {
    try {
      navigator.mediaSession.setActionHandler("play",() => playMusic());
      navigator.mediaSession.setActionHandler("pause",() => pauseMusic());
      navigator.mediaSession.setActionHandler("nexttrack",() => changeMusicTrack(1,{ play:true }));
    } catch (_) {}
  }
  if (musicEnabled) {
    const resumeRememberedMusic = (event) => {
      if (!musicEnabled || !backgroundMusic.paused || event.target.closest?.(".music-player")) return;
      playMusic().then((started) => {
        if (!started) return;
        document.removeEventListener("pointerdown",resumeRememberedMusic,true);
        document.removeEventListener("keydown",resumeRememberedMusic,true);
      });
    };
    document.addEventListener("pointerdown",resumeRememberedMusic,true);
    document.addEventListener("keydown",resumeRememberedMusic,true);
  }
}

