function buildTeleportSelect(selectEl) {
  if (!selectEl) return;
  const parent = selectEl.parentElement;
  
  let trigger = parent.querySelector('.custom-select-trigger');
  if (!trigger) {
    trigger = document.createElement('div');
    trigger.className = 'custom-select-trigger';
    parent.append(trigger);
  }
  
  const selectedOption = selectEl.options[selectEl.selectedIndex] || selectEl.options[0];
  trigger.textContent = selectedOption ? selectedOption.text : '';

  let teleportMenu = document.getElementById(`teleport-${selectEl.id}`);
  if (!teleportMenu) {
    teleportMenu = document.createElement('div');
    teleportMenu.id = `teleport-${selectEl.id}`;
    teleportMenu.className = 'teleport-select-options';
    document.body.append(teleportMenu);
  }

  teleportMenu.replaceChildren();
  Array.from(selectEl.options).forEach((opt) => {
    const optDiv = document.createElement('div');
    optDiv.className = `custom-option ${opt.value === selectEl.value ? 'selected' : ''}`;
    optDiv.textContent = opt.text;

    optDiv.addEventListener('click', (e) => {
      e.stopPropagation();
      selectEl.value = opt.value;
      trigger.textContent = opt.text;
      teleportMenu.classList.remove('open');
      selectEl.dispatchEvent(new Event('change'));
    });
    teleportMenu.append(optDiv);
  });

  trigger.onclick = (e) => {
    e.stopPropagation();
    const isOpen = teleportMenu.classList.contains('open');
    document.querySelectorAll('.teleport-select-options').forEach(m => m.classList.remove('open'));

    if (!isOpen) {
      const rect = trigger.getBoundingClientRect();
      teleportMenu.style.top = `${rect.bottom + window.scrollY + 6}px`;
      teleportMenu.style.left = `${rect.left + window.scrollX}px`;
      teleportMenu.style.width = `${rect.width}px`;
      teleportMenu.classList.add('open');
    }
  };
}

document.addEventListener('click', () => {
  document.querySelectorAll('.teleport-select-options').forEach(m => m.classList.remove('open'));
});

function setLanguage(lang) {
  if (!["en", "zh", "zht"].includes(lang)) lang = "en";
  currentLang = lang;
  localStorage.setItem("landy_lang", lang);
  const documentLanguage = lang === "zht" ? "zh-Hant" : lang === "zh" ? "zh-Hans" : "en";
  document.documentElement.lang = documentLanguage;
  document.body.setAttribute("lang", lang === "zht" ? "zh-Hant" : lang);
  document.body.dataset.language = lang;

  const dict = translations[lang] || translations.en;
  document.querySelectorAll("[data-i18n]").forEach((el) => {
    const key = el.getAttribute("data-i18n");
    if (dict[key]) {
      // 识别是否是需要滚动效果的交互元素，注入防溢出的 Wrapper 遮罩结构
      if (el.matches('.site-nav a, .tab-button, .chip-button')) {
        el.classList.add('roll-target');
        el.innerHTML = `<span class="roll-text-wrapper"><span class="roll-text-inner" data-text="${dict[key]}"><span>${dict[key]}</span></span></span>`;
      } else {
        el.textContent = dict[key];
      }
    }
  });
  document.querySelectorAll("[data-i18n-placeholder]").forEach((el) => {
    const key = el.getAttribute("data-i18n-placeholder");
    if (dict[key]) el.placeholder = dict[key];
  });
  document.querySelectorAll("[data-i18n-aria-label]").forEach((el) => {
    const key = el.getAttribute("data-i18n-aria-label");
    if (dict[key]) el.setAttribute("aria-label", dict[key]);
  });
  document.querySelectorAll(".journey-zh").forEach((el) => {
    if (!el.dataset.zhHans) el.dataset.zhHans = el.textContent;
    el.textContent = lang === "zht" ? toTraditional(el.dataset.zhHans) : el.dataset.zhHans;
  });
  if (pagePrev) pagePrev.setAttribute("aria-label", dict.page_prev);
  if (pageNext) pageNext.setAttribute("aria-label", dict.page_next);
  if (lightboxClose) lightboxClose.setAttribute("aria-label", dict.lightbox_close);
  if (lightboxPrev) lightboxPrev.setAttribute("aria-label", dict.lightbox_prev);
  if (lightboxNext) lightboxNext.setAttribute("aria-label", dict.lightbox_next);
  if (contactDrawerClose) contactDrawerClose.setAttribute("aria-label", dict.contact_collapse);
  if (contactDrawerBackdrop) contactDrawerBackdrop.setAttribute("aria-label", dict.contact_collapse);

  document.querySelectorAll(".lang-label").forEach((label) => {
    label.classList.toggle("active", label.dataset.lang === lang);
  });
  if (langToggleBtn) {
    langToggleBtn.setAttribute("aria-label", lang === "en"
      ? "Switch language: English, Simplified Chinese, Traditional Chinese"
      : lang === "zh"
        ? "切换语言：英文、简体中文、繁体中文"
        : "切換語言：英文、簡體中文、繁體中文");
  }
  syncMusicPlayerLanguage();

  if (products.length && productGrid) {
    fillSelect(categoryFilter, unique(products.map((p) => p.category)), dict.all_collections);
    fillSelect(seasonFilter, unique(products.map((p) => p.season)), dict.all_seasons);
    fillSelect(subcategoryFilter, unique(products.map((p) => p.subcategory)), dict.all_subcategories);
    [categoryFilter, seasonFilter, subcategoryFilter].forEach(buildTeleportSelect);
    renderQuickChips();
    renderProducts();
    if (lightbox?.classList.contains("open") && currentGalleryProducts[activeLightboxIndex]) {
      renderLightboxProduct(currentGalleryProducts[activeLightboxIndex], activeLightboxIndex);
    }
  }
  if (!window.LANDY_MOBILE_JOURNEY) {
    const activeJourneyIndex = Math.max(0, journeyIndex);
    journeyIndex = -1;
    setJourneyScene(activeJourneyIndex);
  }

  const syncLanguageControlGeometry = () => {
    const activeNav = document.querySelector(".site-nav a.active");
    if (activeNav) updateNavCapsulePosition(activeNav);
    const activeTab = document.querySelector(".tab-button.active");
    if (activeTab) updateTabCapsulePosition(activeTab);
  };
  requestAnimationFrame(syncLanguageControlGeometry);
  setTimeout(syncLanguageControlGeometry, 60);
}

function captureLanguageViewport() {
  const sampleY = Math.min(innerHeight - 120, Math.max(120, innerHeight * .46));
  let anchor = document.elementFromPoint(innerWidth / 2, sampleY);
  if (anchor?.closest(".site-header,.lang-switch-standalone")) anchor = null;
  anchor = anchor?.closest("[data-i18n],article,figure,li,section,[id]") || anchor;
  return {
    anchor,
    anchorTop: anchor?.getBoundingClientRect().top ?? sampleY,
    scrollTop: window.scrollY
  };
}

function preserveLanguageViewport(viewport) {
  const html = document.documentElement;
  const body = document.body;
  const previousScrollBehavior = html.style.scrollBehavior;
  const previousHtmlAnchor = html.style.overflowAnchor;
  const previousBodyAnchor = body.style.overflowAnchor;
  html.style.scrollBehavior = "auto";
  html.style.overflowAnchor = "none";
  body.style.overflowAnchor = "none";

  const restore = () => {
    const anchor = viewport.anchor;
    if (anchor?.isConnected) {
      const correction = anchor.getBoundingClientRect().top - viewport.anchorTop;
      if (Math.abs(correction) > .25) window.scrollBy(0, correction);
    } else {
      window.scrollTo(0, viewport.scrollTop);
    }
  };
  restore();
  requestAnimationFrame(restore);
  setTimeout(restore, 90);
  setTimeout(() => {
    restore();
    html.style.scrollBehavior = previousScrollBehavior;
    html.style.overflowAnchor = previousHtmlAnchor;
    body.style.overflowAnchor = previousBodyAnchor;
  }, 560);
}

langToggleBtn?.addEventListener("click", async (event) => {
  const languageOrder = ["en", "zht", "zh"];
  const requestedLanguage = langToggleBtn.__requestedLanguage || event.target.closest(".lang-label")?.dataset.lang;
  delete langToggleBtn.__requestedLanguage;
  if (languageOrder.includes(requestedLanguage) && requestedLanguage === currentLang) return;
  const targetLang = languageOrder.includes(requestedLanguage)
    ? requestedLanguage
    : languageOrder[(languageOrder.indexOf(currentLang) + 1) % languageOrder.length];
  const languageViewport = captureLanguageViewport();
  if (event.detail !== 0) langToggleBtn.blur();
  clearTimeout(langToggleBtn.__switchingTimer);
  langToggleBtn.classList.remove("is-lang-switching");
  langToggleBtn.dataset.langDirection = languageOrder.indexOf(targetLang) > languageOrder.indexOf(currentLang) ? "forward" : "backward";
  void langToggleBtn.offsetWidth;
  langToggleBtn.classList.add("is-lang-switching");
  langToggleBtn.__switchingTimer = setTimeout(() => {
    langToggleBtn.classList.remove("is-lang-switching");
    delete langToggleBtn.dataset.langDirection;
  },880);
  const reduceMotion = matchMedia("(prefers-reduced-motion: reduce)").matches;
  const commitLanguage = () => {
    setLanguage(targetLang);
    preserveLanguageViewport(languageViewport);
    document.dispatchEvent(new Event("languagechange"));
  };
  document.body.classList.add("is-language-transitioning");
  if (!reduceMotion) {
    document.body.classList.add("is-language-fading");
    setTimeout(commitLanguage, 120);
    setTimeout(() => {
      document.body.classList.remove("is-language-fading", "is-language-transitioning");
    }, 440);
  } else {
    commitLanguage();
    document.body.classList.remove("is-language-transitioning");
  }
});

