/* 参考 Lorolabs 算法重构平滑数字递增函数，彻底平滑减速过渡，消除末尾突然跳动感 */
function animateCounters(container) {
  const counters = container.querySelectorAll('.counter-num');
  counters.forEach(counter => {
    if (counter.dataset.animated) return;
    counter.dataset.animated = "true";
    const target = parseInt(counter.dataset.target, 10);
    const duration = 2000; // 优化动画时长为 2 秒，增强顺滑体验
    const start = performance.now();

    function step(currentTime) {
      const elapsed = currentTime - start;
      const progress = Math.min(elapsed / duration, 1);
      
      // Lorolabs 级别的 Ease-Out Exponential (1 - 2^(-10t)) 指数平滑减速算法，末尾极其顺滑
      const easeProgress = progress === 1 ? 1 : 1 - Math.pow(2, -10 * progress);
      const currentVal = Math.floor(easeProgress * target);
      counter.textContent = currentVal.toLocaleString();

      if (progress < 1) {
        requestAnimationFrame(step);
      } else {
        counter.textContent = target.toLocaleString();
      }
    }
    requestAnimationFrame(step);
  });
}

const revealObserver = new IntersectionObserver(
  (entries) => {
    entries.forEach((entry) => {
      if (entry.isIntersecting) {
        entry.target.classList.add("visible");
        if (entry.target.querySelector('.counter-num')) {
          animateCounters(entry.target);
        }
      }
    });
  }, { rootMargin: "220px 0px", threshold: 0.01 }
);
revealItems.forEach((item) => revealObserver.observe(item));

glassItems.forEach((item) => {
  item.addEventListener("pointermove", (event) => {
    const rect = item.getBoundingClientRect();
    const x = ((event.clientX - rect.left) / rect.width) * 100;
    const y = ((event.clientY - rect.top) / rect.height) * 100;
    item.style.setProperty("--mx", `${x}%`);
    item.style.setProperty("--my", `${y}%`);
    item.style.setProperty("--glass-x", `${x}%`);
    item.style.setProperty("--glass-y", `${y}%`);
  });
  item.addEventListener("pointerleave", () => {
    item.style.removeProperty("--glass-x");
    item.style.removeProperty("--glass-y");
  });
});

