window.addEventListener("orientationchange",() => requestAnimationFrame(updateChipState),{ passive:true });

function galleryHash(value, seed = galleryMixSeed) {
  let hash = (2166136261 ^ seed) >>> 0;
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return hash >>> 0;
}

/*
 * Create a stable, varied showroom for the current page view:
 * 1. shuffle products inside each subcategory using the current mix seed;
 * 2. shuffle the subcategory order;
 * 3. deal one product from each group in rounds.
 * This keeps pagination stable while filters are used, but prevents one large
 * source folder from occupying the entire first page.
 */
function diversifyProducts(items) {
  const groups = new Map();
  items.forEach((product) => {
    const key = product.subcategory || product.category || "Other";
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(product);
  });

  const orderedGroups = [...groups.entries()]
    .map(([key, group]) => ({
      key,
      products: [...group].sort((a, b) =>
        galleryHash(a.id, galleryMixSeed ^ galleryHash(key)) -
        galleryHash(b.id, galleryMixSeed ^ galleryHash(key))
      )
    }))
    .sort((a, b) => galleryHash(a.key) - galleryHash(b.key));

  const diversified = [];
  let round = 0;
  let hasProducts = true;
  while (hasProducts) {
    hasProducts = false;
    const rotation = orderedGroups.length ? round % orderedGroups.length : 0;
    for (let index = 0; index < orderedGroups.length; index += 1) {
      const group = orderedGroups[(index + rotation) % orderedGroups.length];
      if (group.products[round]) {
        diversified.push(group.products[round]);
        hasProducts = true;
      }
    }
    round += 1;
  }
  return diversified;
}

function updateGalleryMobileState(resultCount) {
  const dict = translations[currentLang] || translations.en;
  const appliedCount = [categoryFilter, seasonFilter, subcategoryFilter]
    .filter((control) => control && control.value !== "All").length + (productSearch?.value.trim() ? 1 : 0);
  if (activeFilterCount) activeFilterCount.textContent = String(appliedCount);
  if (mobileGalleryCount) mobileGalleryCount.textContent = String(resultCount);
  filterToggle?.classList.toggle("has-filters", appliedCount > 0);

  const journeyStillApplied = galleryJourneyFilter === "Home Decor"
    ? categoryFilter?.value === "Home Decor"
    : subcategoryFilter?.value === galleryJourneyFilter;
  if (galleryJourneyFilter && !journeyStillApplied) galleryJourneyFilter = null;
  if (mobileGalleryJourney) mobileGalleryJourney.hidden = !galleryJourneyFilter;
  if (mobileGalleryJourneyLabel) mobileGalleryJourneyLabel.textContent = galleryJourneyFilter ? displayLabel(galleryJourneyFilter) : "";

  if (!mobileActiveFilters) return;
  const filters = [];
  if (categoryFilter?.value !== "All") filters.push(["category", categoryFilter.value]);
  if (seasonFilter?.value !== "All") filters.push(["season", seasonFilter.value]);
  if (subcategoryFilter?.value !== "All") filters.push(["subcategory", subcategoryFilter.value]);
  if (productSearch?.value.trim()) filters.push(["search", `“${productSearch.value.trim()}”`]);
  mobileActiveFilters.replaceChildren();
  filters.forEach(([type, value]) => {
    const button = document.createElement("button");
    button.type = "button";
    button.dataset.clearFilter = type;
    button.setAttribute("aria-label", `${dict.filter_remove} ${displayLabel(value)}`);
    const label = document.createElement("span");
    label.textContent = displayLabel(value);
    const close = document.createElement("i");
    close.textContent = "×";
    close.setAttribute("aria-hidden", "true");
    button.append(label, close);
    mobileActiveFilters.append(button);
  });
}

function clearGalleryFilter(type) {
  currentProductPage = 1;
  if (type === "category" && categoryFilter) categoryFilter.value = "All";
  if (type === "season" && seasonFilter) seasonFilter.value = "All";
  if (type === "subcategory" && subcategoryFilter) subcategoryFilter.value = "All";
  if (type === "search" && productSearch) productSearch.value = "";
  if (type === "category" || type === "season") updateCascadingFilters();
  renderProducts();
}

function renderProducts() {
  if (!productGrid) return;
  const token = ++galleryRenderToken;
  clearTimeout(galleryRenderTimer);
  const currentCards = [...productGrid.querySelectorAll(".product-card")];
  const gridRect = productGrid.getBoundingClientRect();
  const resultsLine = document.querySelector(".gallery-results-line");
  const stickyStack = document.querySelector(".gallery-mobile-sticky-stack");
  const stickyOffset = Math.min((stickyStack?.getBoundingClientRect().height || 0)+82,innerHeight*.55);
  const resultsReturnTarget = touchOnlyInput.matches && !document.body.classList.contains("modal-open") &&
    currentCards.length && gridRect.top < 0 && gridRect.bottom > stickyOffset && resultsLine
      ? Math.max(0,scrollY+resultsLine.getBoundingClientRect().top-stickyOffset)
      : null;
  if (!currentCards.length || matchMedia("(prefers-reduced-motion: reduce)").matches) {
    productGrid.classList.remove("is-leaving");
    commitProductRender(resultsReturnTarget);
    return;
  }
  productGrid.classList.remove("is-updating");
  productGrid.classList.add("is-leaving");
  galleryRenderTimer = setTimeout(() => {
    if (token !== galleryRenderToken) return;
    productGrid.classList.remove("is-leaving");
    commitProductRender(resultsReturnTarget);
  },140);
}

function commitProductRender(resultsReturnTarget = null) {
  if (!productGrid) return;
  const dict = translations[currentLang] || translations.en;
  const filtered = products.filter(productMatches);
  const arranged = diversifyProducts(filtered);
  currentGalleryProducts = arranged;
  productGrid.setAttribute("aria-busy", "true");
  productGrid.classList.add("is-updating");
  if (galleryTransitionFrame) cancelAnimationFrame(galleryTransitionFrame);
  galleryCount.textContent = String(filtered.length);
  if (galleryInlineCount) galleryInlineCount.textContent = String(filtered.length);
  if (galleryCurrentLabel) {
    const activeValue = subcategoryFilter?.value !== "All" ? subcategoryFilter.value
      : seasonFilter?.value !== "All" ? seasonFilter.value
      : categoryFilter?.value !== "All" ? categoryFilter.value
      : null;
    galleryCurrentLabel.textContent = activeValue ? displayLabel(activeValue) : dict.all_products;
  }
  updateGalleryMobileState(filtered.length);
  updateChipState();

  if (!filtered.length) {
    const emptyState = document.createElement("div");
    emptyState.className = "empty-gallery";
    emptyState.innerHTML = `<strong>${dict.empty_gallery}</strong><button type="button">${dict.tool_reset}</button>`;
    emptyState.querySelector("button")?.addEventListener("click", () => resetFilters?.click());
    productGrid.replaceChildren(emptyState);
    if (galleryPagination) galleryPagination.hidden = true;
    galleryTransitionFrame = requestAnimationFrame(() => {
      productGrid.classList.remove("is-updating");
      productGrid.setAttribute("aria-busy", "false");
      if (Number.isFinite(resultsReturnTarget)) scrollTo({top:resultsReturnTarget,behavior:"smooth"});
      galleryTransitionFrame = 0;
    });
    return;
  }

  const pageCount = Math.max(1, Math.ceil(filtered.length / PRODUCTS_PER_PAGE));
  currentProductPage = Math.min(currentProductPage, pageCount);
  const pageStart = (currentProductPage - 1) * PRODUCTS_PER_PAGE;
  const visibleProducts = arranged.slice(pageStart, pageStart + PRODUCTS_PER_PAGE);
  if (galleryPagination) galleryPagination.hidden = pageCount <= 1;
  if (pageStatus) pageStatus.textContent = `${currentProductPage} / ${pageCount}`;
  if (pagePrev) pagePrev.disabled = currentProductPage === 1;
  if (pageNext) pageNext.disabled = currentProductPage === pageCount;

  productGrid.replaceChildren();
  visibleProducts.forEach((product,cardIndex) => {
    const productDisplayTitle = getProductDisplayTitle(product);
    const card = document.createElement("button");
    card.className = "product-card gallery-card-enter"; card.type = "button";
    card.style.setProperty("--card-order",String(Math.min(cardIndex,7)));
    card.dataset.productId = product.id;
    card.innerHTML = `
      <img data-src="${product.image}" alt="${productDisplayTitle}" loading="lazy" decoding="async" fetchpriority="low">
      <span class="product-info">
        <strong>${productDisplayTitle}</strong>
        <span>${displayLabel(product.season)} · ${displayLabel(product.category)}</span>
        <em>${dict.product_view}<i aria-hidden="true">↗</i></em>
      </span>`;
    let touchPointer = null;
    let touchStartX = 0;
    let touchStartY = 0;
    let touchMoved = false;
    let suppressSyntheticClick = false;
    card.addEventListener("pointerdown", (event) => {
      if (event.pointerType === "mouse") return;
      touchPointer = event.pointerId;
      touchStartX = event.clientX;
      touchStartY = event.clientY;
      touchMoved = false;
      card.setPointerCapture?.(touchPointer);
    });
    card.addEventListener("pointermove", (event) => {
      if (event.pointerId !== touchPointer) return;
      if (Math.hypot(event.clientX-touchStartX,event.clientY-touchStartY) > 10) touchMoved = true;
    });
    card.addEventListener("pointercancel", () => {
      suppressSyntheticClick = true;
      touchPointer = null;
      setTimeout(() => { suppressSyntheticClick = false; },450);
    });
    card.addEventListener("pointerup", (event) => {
      if (event.pointerId !== touchPointer) return;
      event.preventDefault();
      event.stopPropagation();
      suppressSyntheticClick = true;
      touchPointer = null;
      const blockFollowupClick = (clickEvent) => {
        clickEvent.preventDefault();
        clickEvent.stopImmediatePropagation();
      };
      document.addEventListener("click",blockFollowupClick,true);
      setTimeout(() => document.removeEventListener("click",blockFollowupClick,true),120);
      if (!touchMoved) openLightbox(product,card);
      setTimeout(() => { suppressSyntheticClick = false; },450);
    });
    card.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      if (!suppressSyntheticClick) openLightbox(product,card);
    });
    productGrid.append(card);
  });
  if (galleryPreheatEnabled) warmGalleryFirstPage();
  galleryTransitionFrame = requestAnimationFrame(() => {
    productGrid.classList.remove("is-updating");
    productGrid.setAttribute("aria-busy", "false");
    if (Number.isFinite(resultsReturnTarget)) scrollTo({top:resultsReturnTarget,behavior:"smooth"});
    galleryTransitionFrame = 0;
    setTimeout(() => {
      productGrid.querySelectorAll(".gallery-card-enter").forEach((card) => card.classList.remove("gallery-card-enter"));
    },720);
  });
}

function renderLightboxProduct(product, index = activeLightboxIndex) {
  if (!lightbox || !lightboxImage) return;
  const dict = translations[currentLang] || translations.en;
  const productDisplayTitle = getProductDisplayTitle(product);
  activeLightboxIndex = index;
  lightbox.classList.add("is-switching");
  lightboxImage.src = product.image; lightboxImage.alt = `${productDisplayTitle} product preview`;
  lightboxTitle.textContent = productDisplayTitle; lightboxPath.textContent = product.sourceFolder.split(" / ").map(displayLabel).join(" / ");
  lightboxMeta.textContent = `${displayLabel(product.season)} · ${displayLabel(product.category)} · ${displayLabel(product.subcategory)}`;
  if (lightboxSeason) lightboxSeason.textContent = displayLabel(product.season);
  if (lightboxCollection) lightboxCollection.textContent = displayLabel(product.category);
  if (lightboxCategory) lightboxCategory.textContent = displayLabel(product.subcategory);
  if (lightboxReference) lightboxReference.textContent = product.id.toUpperCase();
  if (lightboxPosition) {
    const positionText = dict.lightbox_position
      .replace("{current}", String(index + 1))
      .replace("{total}", String(currentGalleryProducts.length));
    lightboxPosition.textContent = positionText;
    if (lightboxMobilePosition) lightboxMobilePosition.textContent = positionText;
  }
  if (lightboxPrev) lightboxPrev.disabled = index <= 0;
  if (lightboxNext) lightboxNext.disabled = index >= currentGalleryProducts.length - 1;
  [currentGalleryProducts[index - 1], currentGalleryProducts[index + 1]].filter(Boolean).forEach((nearbyProduct) => {
    const preload = new Image();
    preload.src = nearbyProduct.image;
  });
  requestAnimationFrame(() => lightbox.classList.remove("is-switching"));
}

function openLightbox(product, trigger = document.activeElement) {
  if (!lightbox || !lightboxImage) return;
  const productIndex = currentGalleryProducts.findIndex((item) => item.id === product.id);
  if (productIndex < 0) currentGalleryProducts = [product];
  lightboxReturnFocus = trigger instanceof HTMLElement ? trigger : null;
  renderLightboxProduct(product, Math.max(0, productIndex));
  lightbox.classList.add("open"); lightbox.setAttribute("aria-hidden", "false"); document.body.classList.add("modal-open");
  setTimeout(() => {
    if (lightbox.classList.contains("open") && !touchOnlyInput.matches) lightboxClose?.focus({ preventScroll: true });
  }, 280);
}

function navigateLightbox(direction) {
  if (!lightbox?.classList.contains("open")) return;
  const nextIndex = Math.max(0, Math.min(currentGalleryProducts.length - 1, activeLightboxIndex + direction));
  if (nextIndex === activeLightboxIndex) return;
  const nextPage = Math.floor(nextIndex / PRODUCTS_PER_PAGE) + 1;
  if (nextPage !== currentProductPage) {
    currentProductPage = nextPage;
    renderProducts();
  }
  renderLightboxProduct(currentGalleryProducts[nextIndex], nextIndex);
}

function closeLightbox(options = {}) {
  if (!lightbox?.classList.contains("open")) return;
  const restoreFocus = options.restoreFocus !== false;
  const activeProduct = currentGalleryProducts[activeLightboxIndex];
  lightbox.classList.remove("open"); lightbox.setAttribute("aria-hidden", "true"); document.body.classList.remove("modal-open");
  const currentCard = activeProduct ? productGrid?.querySelector(`[data-product-id="${activeProduct.id}"]`) : null;
  const focusTarget = currentCard || (lightboxReturnFocus?.isConnected ? lightboxReturnFocus : null);
  if (restoreFocus && !touchOnlyInput.matches) requestAnimationFrame(() => focusTarget?.focus({ preventScroll: true }));
}

function openContactDrawer() {
  if (!contactSection || !contactDrawerClose || !contactDrawerBackdrop) return;
  const activeProduct = currentGalleryProducts[activeLightboxIndex];
  const dict = translations[currentLang] || translations.en;
  const lightboxIsOpen = lightbox?.classList.contains("open");
  contactDrawerReturnFocus = lightboxIsOpen
    ? lightboxInquiry
    : activeProduct
      ? productGrid?.querySelector(`[data-product-id="${activeProduct.id}"]`)
      : lightboxReturnFocus;
  if (lightboxIsOpen) {
    if (lightbox.contains(document.activeElement)) document.activeElement.blur();
    lightbox.classList.add("is-behind-contact");
    lightbox.setAttribute("aria-hidden", "true");
    lightbox.setAttribute("aria-modal", "false");
  }
  if (activeProduct && contactProductContext) {
    const productTitle = getProductDisplayTitle(activeProduct);
    contactProductContext.hidden = false;
    if (contactProductImage) { contactProductImage.src = activeProduct.image; contactProductImage.alt = productTitle; }
    if (contactProductTitle) contactProductTitle.textContent = productTitle;
    if (contactProductReference) contactProductReference.textContent = activeProduct.id.toUpperCase();
    contactSection.querySelectorAll('a[href^="mailto:"]').forEach((link) => {
      const address = link.getAttribute("href").split("?")[0];
      const subject = `${dict.inquiry_subject}: ${productTitle}`;
      const body = `${dict.inquiry_body}\n${productTitle}\n${activeProduct.id.toUpperCase()}`;
      link.href = `${address}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
    });
  }
  clearTimeout(contactDrawerTimer);
  contactSection.classList.add("is-contact-drawer");
  contactSection.setAttribute("role", "dialog");
  contactSection.setAttribute("aria-modal", "true");
  contactDrawerBackdrop.classList.add("is-open");
  document.body.classList.add("contact-drawer-open");
  contactSection.scrollTop = 0;
  requestAnimationFrame(() => {
    contactSection.classList.add("is-open");
    if (!touchOnlyInput.matches) setTimeout(() => contactDrawerClose.focus({ preventScroll: true }), 360);
  });
}

function closeContactDrawer() {
  if (!contactSection?.classList.contains("is-contact-drawer")) return;
  contactSection.classList.remove("is-open");
  contactDrawerBackdrop?.classList.remove("is-open");
  document.body.classList.remove("contact-drawer-open");
  const focusTarget = contactDrawerReturnFocus?.isConnected ? contactDrawerReturnFocus : null;
  contactDrawerTimer = setTimeout(() => {
    contactSection.classList.remove("is-contact-drawer");
    contactSection.removeAttribute("role");
    contactSection.removeAttribute("aria-modal");
    if (lightbox?.classList.contains("open")) {
      lightbox.classList.remove("is-behind-contact");
      lightbox.setAttribute("aria-hidden", "false");
      lightbox.setAttribute("aria-modal", "true");
    }
    if (!touchOnlyInput.matches) focusTarget?.focus({ preventScroll: true });
  }, 420);
}

function initBrandMarquee() {
  const track1 = document.querySelector("#marquee-track-1"), track2 = document.querySelector("#marquee-track-2");
  const track3 = document.querySelector("#marquee-track-3"), track4 = document.querySelector("#marquee-track-4");
  if (!track1 || !track2) return;
  const partners = window.LANDY_PARTNERS || [];
  const createBrandItems = (items = partners) => items.map(partner => {
    const item = document.createElement('div');
    const brandKey = partner.key || partner.name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
    item.className = `brand-item-lorolabs brand-${brandKey}`;
    const icon = document.createElement('div');
    icon.className = 'brand-icon-box';
    const mark = document.createElement('span');
    mark.className = 'brand-mark-text';
    mark.textContent = partner.mark;
    icon.append(mark);
    const name = document.createElement('span');
    name.className = 'brand-name-text';
    name.textContent = partner.name;
    item.append(icon, name);
    return item;
  });
  track1.replaceChildren(...createBrandItems()); track2.replaceChildren(...createBrandItems());
  if (track3 && track4) {
    const split = Math.ceil(partners.length / 2);
    const reverseRowPartners = [...partners.slice(split), ...partners.slice(0, split)];
    track3.replaceChildren(...createBrandItems(reverseRowPartners));
    track4.replaceChildren(...createBrandItems(reverseRowPartners));
  }
}

/* 严格基于“产品体系”思维导图建立的多级联动关系树 */
const PRODUCT_SYSTEM_TREE = {
  "Home Decor": {
    seasons: ["Everyday"],
    subcategories: ["Home Decor"]
  },
  "Seasonal Gifts": {
    seasons: ["SPRING", "WINTER"],
    subcategoriesBySeason: {
      "SPRING": [
        "GARDEN",
        "ANGEL",
        "GIFTS",
        "COASTLINE",
        "EASTER",
        "VALENTINE'S DAY",
        "AMERICANA JULY 4th",
        "IRISH COLLECTION",
        "FARMHOUSE"
      ],
      "WINTER": [
        "HALLOWEN",
        "THANKSGIVING",
        "CHRISTMAS"
      ]
    }
  }
};

/* 级联更新筛选器选项的函数 */
function updateCascadingFilters() {
  const selectedCategory = categoryFilter?.value || "All";
  const selectedSeason = seasonFilter?.value || "All";
  const dict = translations[currentLang] || translations.en;

  // 1. 根据产品系列更新【销售季节】
  let availableSeasons = [];
  if (selectedCategory === "All") {
    availableSeasons = unique(products.map(p => p.season));
  } else if (PRODUCT_SYSTEM_TREE[selectedCategory]) {
    availableSeasons = PRODUCT_SYSTEM_TREE[selectedCategory].seasons;
  }

  // 若当前选中的季节不在可用范围内，重置为 All
  if (selectedSeason !== "All" && !availableSeasons.includes(selectedSeason)) {
    seasonFilter.value = "All";
  }
  fillSelect(seasonFilter, availableSeasons, dict.all_seasons);

  // 2. 根据产品系列 + 销售季节更新【细分类别】
  let availableSubcats = [];
  const currentSeason = seasonFilter.value;

  if (selectedCategory === "All") {
    if (currentSeason === "All") {
      availableSubcats = unique(products.map(p => p.subcategory));
    } else {
      availableSubcats = unique(products.filter(p => p.season === currentSeason).map(p => p.subcategory));
    }
  } else if (selectedCategory === "Home Decor") {
    availableSubcats = PRODUCT_SYSTEM_TREE["Home Decor"].subcategories;
  } else if (selectedCategory === "Seasonal Gifts") {
    if (currentSeason === "All") {
      availableSubcats = [
        ...PRODUCT_SYSTEM_TREE["Seasonal Gifts"].subcategoriesBySeason["SPRING"],
        ...PRODUCT_SYSTEM_TREE["Seasonal Gifts"].subcategoriesBySeason["WINTER"]
      ];
    } else if (PRODUCT_SYSTEM_TREE["Seasonal Gifts"].subcategoriesBySeason[currentSeason]) {
      availableSubcats = PRODUCT_SYSTEM_TREE["Seasonal Gifts"].subcategoriesBySeason[currentSeason];
    }
  }

  const selectedSub = subcategoryFilter?.value || "All";
  if (selectedSub !== "All" && !availableSubcats.includes(selectedSub)) {
    subcategoryFilter.value = "All";
  }
  fillSelect(subcategoryFilter, availableSubcats, dict.all_subcategories);

  // 3. 重新渲染下拉菜单 UI
  [categoryFilter, seasonFilter, subcategoryFilter].forEach(buildTeleportSelect);
}

